CREATE INDEX ix_invoices_purchase_order_id ON invoices (purchase_order_id);

CREATE INDEX ix_invoices_status ON invoices (status);

CREATE TABLE payments (
    id SERIAL NOT NULL, 
    invoice_id INTEGER NOT NULL, 
    amount NUMERIC(12, 2) NOT NULL, 
    bank_transaction_id VARCHAR(255), 
    payment_date TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id), 
    CONSTRAINT fk_payments_invoice FOREIGN KEY(invoice_id) REFERENCES invoices (id)
);

CREATE INDEX ix_payments_id ON payments (id);

CREATE INDEX ix_payments_invoice_id ON payments (invoice_id);

CREATE TABLE unresolved_transactions (
    id SERIAL NOT NULL, 
    amount NUMERIC(12, 2) NOT NULL, 
    description TEXT, 
    bank_date TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    status VARCHAR(50) DEFAULT '�� ������������' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id)
);

CREATE INDEX ix_unresolved_transactions_id ON unresolved_transactions (id);

CREATE TABLE production_tasks (
    id SERIAL NOT NULL, 
    project_id INTEGER NOT NULL, 
    status VARCHAR(50) DEFAULT '�������� ������������' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    CONSTRAINT fk_production_tasks_project FOREIGN KEY(project_id) REFERENCES projects (id)
);

CREATE INDEX ix_production_tasks_id ON production_tasks (id);

CREATE INDEX ix_production_tasks_project_id ON production_tasks (project_id);

